$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-production-dual-id-new-permit-issuer-v0.1.0/test_custom_app_production_dual_id_new_permit_issuer.ps1')
. (Join-Path $root 'validation/custom-app-production-permit-reservation-v0.1.0/custom-app-production-permit-reservation.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-dual-id-new-permit-reservation.ps1')

function Assert-DINPRTrue([bool]$v,[string]$m){if(-not $v){throw $m}}
function Assert-DINPRFalse([bool]$v,[string]$m){if($v){throw $m}}
function Assert-DINPREq($a,$b,[string]$m){if([string]$a -cne [string]$b){throw "$m actual=<$a> expected=<$b>"}}
function Copy-DINPR($x){return (($x|ConvertTo-Json -Depth 100)|ConvertFrom-Json)}
function Assert-DINPRDenied($r,[string]$label){Assert-DINPRFalse ([bool]$r.ok) "$label unexpectedly reserved";Assert-DINPRFalse ([bool]$r.reservation_created) "$label created reservation";Assert-DINPRFalse ([bool]$r.reservation_persisted) "$label persisted reservation";Assert-DINPRFalse ([bool]$r.executor_may_start) "$label executor escaped";Assert-DINPRFalse ([bool]$r.production_mutation_authorized) "$label mutation authority escaped"}

function New-DINPRFixtureV010 {
    param([Parameter(Mandatory=$true)][string]$Label)
    $i=New-DINPIIssuerFixtureV010 ('reservation-'+$Label)
    $issuer=Invoke-DINPIIssuerV010 $i
    Assert-DINPRTrue ([bool]$issuer.ok) ("$Label issuer setup denied: $([string]$issuer.reason)")
    return [pscustomobject]@{i=$i;issuer=$issuer;state=(New-CustomAppProductionPermitReservationStateV010);at=$i.f.q.at.AddSeconds(1)}
}
function Invoke-DINPRV010 {
    param([Parameter(Mandatory=$true)]$Q,[AllowNull()]$IssuerResult=$null,[AllowNull()]$ReservationState=$null,[AllowNull()]$Bundle=$null,[AllowNull()]$CurrentBaseline=$null,[AllowNull()]$PriorReadinessReceipt=$null,[AllowNull()]$IssuanceAdmissionReceipt=$null,[AllowNull()][byte[]]$Key=$null,[AllowNull()][string]$NewPermitId=$null,[int64]$ExpectedRevision=-1,[DateTimeOffset]$At=[DateTimeOffset]::MinValue)
    $I=$Q.i;$F=$I.f
    if($null -eq $IssuerResult){$IssuerResult=$Q.issuer};if($null -eq $ReservationState){$ReservationState=$Q.state};if($null -eq $Bundle){$Bundle=$F.q.bundle};if($null -eq $CurrentBaseline){$CurrentBaseline=$F.live.baseline};if($null -eq $PriorReadinessReceipt){$PriorReadinessReceipt=$F.prior};if($null -eq $IssuanceAdmissionReceipt){$IssuanceAdmissionReceipt=$I.admission};if($null -eq $Key){$Key=$script:DINPIKey};if([string]::IsNullOrWhiteSpace($NewPermitId)){$NewPermitId=[string]$F.new_id};if($ExpectedRevision -lt 0){$ExpectedRevision=[int64]$ReservationState.revision};if($At -eq [DateTimeOffset]::MinValue){$At=$Q.at}
    return Invoke-CustomAppProductionDualIdNewPermitReservationV010 -Name ([string]$Bundle.lifecycle.name) -LifecycleRow $Bundle.lifecycle -ProvenanceRow $Bundle.provenance -BindingRow $Bundle.binding -StageResult $Bundle.stage -ShadowResult $Bundle.shadow -HousekeepingResult $F.q.house.result -AllowedRoot $F.q.x.f.trust -StoreDirectory $F.q.x.f.store -HistoricalPermitTransactionId ([string]$F.q.house.result.permit_transaction_id) -HistoricalJournalTransactionId ([string]$F.q.house.result.journal_transaction_id) -NewPermitTransactionId $NewPermitId -LocalAppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.local) -AppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.roaming) -CurrentBaseline $CurrentBaseline -ShadowProtocolQualification $F.live.shadow -LiveAttestedQualification $F.live.live -PriorReadinessReceipt $PriorReadinessReceipt -IssuanceAdmissionReceipt $IssuanceAdmissionReceipt -IssuerResult $IssuerResult -SessionKey $Key -ReservationState $ReservationState -ExpectedRevision $ExpectedRevision -Now $At
}

$count=0
$valid=New-DINPRFixtureV010 'valid';$r=Invoke-DINPRV010 $valid
Assert-DINPRTrue ([bool]$r.ok) ('valid reservation denied: '+[string]$r.reason);Assert-DINPREq $r.reason 'dual-id-new-permit-reserved-in-memory-transaction-bound-requires-atomic-persistence' 'valid reason';Assert-DINPRTrue ([bool]$r.reservation_created) 'valid reservation not created';Assert-DINPRFalse ([bool]$r.reservation_persisted) 'valid reservation unexpectedly persisted';Assert-DINPRTrue ([bool]$r.transaction_binding_verified) 'transaction binding not preserved';Assert-DINPREq $r.receipt.new_permit_transaction_id $valid.i.f.new_id 'new transaction continuity';Assert-DINPREq $r.receipt.transaction_binding_hmac_sha256 $valid.issuer.receipt.transaction_binding_hmac_sha256 'binding HMAC continuity';Assert-DINPREq $r.receipt.reservation_id $r.next_state.reservations[0].reservation_id 'reservation id continuity';Assert-DINPRFalse ($null -ne $r.next_state.reservations[0].PSObject.Properties['new_permit_transaction_id']) 'generic reservation row wire format changed';$c=Test-CustomAppProductionDualIdNewPermitReservationReceiptV010 -Receipt $r.receipt -Now $valid.at.AddSeconds(1);Assert-DINPRTrue ([bool]$c.ok) ('valid wrapper receipt invalid: '+[string]$c.reason);$validResult=$r;$count++

$wrongKey=New-DINPRFixtureV010 'wrong-key';$r=Invoke-DINPRV010 -Q $wrongKey -Key $script:DINPIWrongKey;Assert-DINPRDenied $r 'wrong key';Assert-DINPRTrue ([string]$r.reason -like 'dual-id-new-permit-reservation-issuer-receipt-invalid:*transaction-binding-hmac-mismatch') ('wrong key reason '+[string]$r.reason);$count++

$wrongTx=New-DINPRFixtureV010 'wrong-new-tx';$r=Invoke-DINPRV010 -Q $wrongTx -NewPermitId (Get-DINPIANewTransactionId 'reservation-other-tx');Assert-DINPRDenied $r 'wrong new transaction';Assert-DINPREq $r.reason 'dual-id-new-permit-reservation-issuer-identity-or-transaction-mismatch' 'wrong new tx reason';$count++

$bindingTamper=New-DINPRFixtureV010 'binding-tamper';$bad=Copy-DINPR $bindingTamper.issuer;$bad.receipt.new_permit_transaction_id=Get-DINPIANewTransactionId 'reservation-transplant';$bad.receipt.issuer_fingerprint=Get-CustomAppProductionDualIdNewPermitIssuerSha256V010 (Get-CustomAppProductionDualIdNewPermitIssuerReceiptMaterialV010 -Receipt $bad.receipt);$r=Invoke-DINPRV010 -Q $bindingTamper -IssuerResult $bad;Assert-DINPRDenied $r 'binding transplant';Assert-DINPRTrue ([string]$r.reason -like '*transaction-binding-hmac-mismatch') ('binding transplant reason '+[string]$r.reason);$count++

$permitTamper=New-DINPRFixtureV010 'permit-tamper';$bad=Copy-DINPR $permitTamper.issuer;$bad.permit.token_id=('f'*64);$r=Invoke-DINPRV010 -Q $permitTamper -IssuerResult $bad;Assert-DINPRDenied $r 'permit receipt mismatch';Assert-DINPREq $r.reason 'dual-id-new-permit-reservation-permit-receipt-identity-mismatch' 'permit mismatch reason';$count++

$revision=New-DINPRFixtureV010 'revision';$r=Invoke-DINPRV010 -Q $revision -ExpectedRevision 1;Assert-DINPRDenied $r 'revision conflict';Assert-DINPRTrue ([string]$r.reason -like 'dual-id-new-permit-reservation-generic-reservation-denied:reservation-state-revision-conflict') ('revision reason '+[string]$r.reason);$count++

$replay=New-DINPRFixtureV010 'replay';$first=Invoke-DINPRV010 $replay;Assert-DINPRTrue ([bool]$first.ok) 'replay setup first reservation failed';$r=Invoke-DINPRV010 -Q $replay -ReservationState $first.next_state -ExpectedRevision 1;Assert-DINPRDenied $r 'same-token replay';Assert-DINPRTrue ([string]$r.reason -like 'dual-id-new-permit-reservation-generic-reservation-denied:permit-already-reserved-token') ('replay reason '+[string]$r.reason);Assert-DINPREq $r.next_state.revision 1 'replay changed state';$count++

$live=New-DINPRFixtureV010 'live-drift';$baseline=Copy-DINPR $live.i.f.live.baseline;$baseline.tree_sha256=('8'*64);$r=Invoke-DINPRV010 -Q $live -CurrentBaseline $baseline;Assert-DINPRDenied $r 'live drift';Assert-DINPRTrue ([string]$r.reason -like 'dual-id-new-permit-reservation-pre-admission-denied:*') ('live drift reason '+[string]$r.reason);$count++

$post=New-DINPRFixtureV010 'post-drift';$F=$post.i.f;$pre=Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Name ([string]$F.q.bundle.lifecycle.name) -LifecycleRow $F.q.bundle.lifecycle -ProvenanceRow $F.q.bundle.provenance -BindingRow $F.q.bundle.binding -StageResult $F.q.bundle.stage -ShadowResult $F.q.bundle.shadow -HousekeepingResult $F.q.house.result -AllowedRoot $F.q.x.f.trust -StoreDirectory $F.q.x.f.store -HistoricalPermitTransactionId ([string]$F.q.house.result.permit_transaction_id) -HistoricalJournalTransactionId ([string]$F.q.house.result.journal_transaction_id) -NewPermitTransactionId ([string]$F.new_id) -LocalAppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.local) -AppDataRoot ([string]$F.q.x.f.x.fixture.q.persistence.roaming) -CurrentBaseline $F.live.baseline -ShadowProtocolQualification $F.live.shadow -LiveAttestedQualification $F.live.live -PriorReadinessReceipt $F.prior -Now $post.at
Assert-DINPRTrue ([bool]$pre.ok) 'post drift pre fixture failed';$script:DINPRPre=Copy-DINPR $pre.receipt;$script:DINPRPost=Copy-DINPR $pre.receipt;$script:DINPRPost.current_remote_commit_sha=('d'*40);$script:DINPRPost.issuance_admission_fingerprint=Get-CustomAppProductionDualIdNewPermitIssuanceAdmissionSha256V010 (Get-CustomAppProductionDualIdNewPermitIssuanceAdmissionMaterialV010 $script:DINPRPost);$script:DINPRCalls=0;$orig=(Get-Command Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -CommandType Function).ScriptBlock
try {
    Set-Item -Path Function:\Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Value {param($Name,$LifecycleRow,$ProvenanceRow,$BindingRow,$StageResult,$ShadowResult,$HousekeepingResult,$AllowedRoot,$StoreDirectory,$HistoricalPermitTransactionId,$HistoricalJournalTransactionId,$NewPermitTransactionId,$LocalAppDataRoot,$AppDataRoot,$CurrentBaseline,$ShadowProtocolQualification,$LiveAttestedQualification,$PriorReadinessReceipt,$Now,$MaxRemoteObservationAgeHours);$script:DINPRCalls++;if($script:DINPRCalls -eq 1){return [pscustomobject]@{ok=$true;reason='fixture-pre';receipt=$script:DINPRPre}};return [pscustomobject]@{ok=$true;reason='fixture-post';receipt=$script:DINPRPost}}
    $r=Invoke-DINPRV010 $post
} finally {Set-Item -Path Function:\Resolve-CustomAppProductionDualIdNewPermitIssuanceAdmissionV010 -Value $orig;$script:DINPRCalls=0}
Assert-DINPRDenied $r 'post reservation drift';Assert-DINPREq $r.reason 'dual-id-new-permit-reservation-admission-drift-during-reservation' 'post drift reason';Assert-DINPREq $r.next_state.revision 0 'post drift leaked in-memory reservation';$count++

$expired=New-DINPRFixtureV010 'expired';$r=Invoke-DINPRV010 -Q $expired -At $expired.i.f.q.at.AddSeconds(6);Assert-DINPRDenied $r 'expired issuer window';Assert-DINPRTrue ([string]$r.reason -like 'dual-id-new-permit-reservation-issuer-receipt-invalid:*reservation-window-expired') ('expired issuer reason '+[string]$r.reason);$count++

$tampered=Copy-DINPR $validResult.receipt;$tampered.permit_durably_reserved=$true;$tampered.reservation_fingerprint=Get-CustomAppProductionDualIdNewPermitReservationSha256V010 (Get-CustomAppProductionDualIdNewPermitReservationReceiptMaterialV010 -Receipt $tampered);$c=Test-CustomAppProductionDualIdNewPermitReservationReceiptV010 -Receipt $tampered -Now $valid.at.AddSeconds(1);Assert-DINPRFalse ([bool]$c.ok) 'durable reservation authority tamper accepted';Assert-DINPRTrue ([string]$c.reason -like '*authority-or-persistence-escaped-permit_durably_reserved') 'durable tamper reason';$count++

$tampered=Copy-DINPR $validResult.receipt;$tampered.post_reservation_issuance_admission_fingerprint=('0'*64);$tampered.reservation_fingerprint=Get-CustomAppProductionDualIdNewPermitReservationSha256V010 (Get-CustomAppProductionDualIdNewPermitReservationReceiptMaterialV010 -Receipt $tampered);$c=Test-CustomAppProductionDualIdNewPermitReservationReceiptV010 -Receipt $tampered -Now $valid.at.AddSeconds(1);Assert-DINPRFalse ([bool]$c.ok) 'pre/post admission drift receipt accepted';Assert-DINPREq $c.reason 'dual-id-new-permit-reservation-pre-post-admission-drift' 'pre/post drift reason';$count++

$until=[DateTimeOffset]::Parse([string]$validResult.receipt.persistence_eligible_until);$c=Test-CustomAppProductionDualIdNewPermitReservationReceiptV010 -Receipt $validResult.receipt -Now $until;Assert-DINPRFalse ([bool]$c.ok) 'expired persistence window accepted';Assert-DINPREq $c.reason 'dual-id-new-permit-reservation-persistence-window-expired' 'persistence expiry reason';$count++

if($count -ne 12){throw "dual-ID new permit reservation matrix count mismatch $count"}
Write-Host "CUSTOM_APP_PRODUCTION_DUAL_ID_NEW_PERMIT_RESERVATION_MATRIX_PASS cases=$count generic_reservation_wire_unchanged=true transaction_binding_revalidated=true ids_pairwise_distinct=true replay_denied=true post_drift_discards_state=true reservation_persisted=false zero_authority=true"
